def esc(s):
    # Java সোর্সে বাংলা অক্ষর \uXXXX আকারে লেখা, যাতে এনকোডিং নিয়ে কোনো সমস্যা না হয়
    out = []
    for ch in s:
        o = ord(ch)
        if o < 128:
            out.append(ch)
        elif o < 0x10000:
            out.append('\\u%04x' % o)
        else:
            o -= 0x10000
            out.append('\\u%04x\\u%04x' % (0xD800 + (o >> 10), 0xDC00 + (o & 0x3FF)))
    return ''.join(out)


def write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        f.write(text)


javadir = os.path.join(MAIN, 'java', *APPID.split('.'))
for name, text in FILES.items():
    if name.startswith('java/'):
        text = text.replace('package com.madrasa.management;', 'package %s;' % APPID)
        write(os.path.join(javadir, name[5:]), esc(text))
    else:
        write(os.path.join(MAIN, 'res', name), text)
import base64
for name, b64 in BINARY.items():
    path = os.path.join(MAIN, 'res', name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb') as f:
        f.write(base64.b64decode(b64))
print('ফাইল বসানো হয়েছে:', len(FILES) + len(BINARY))

# Manifest: উইজেট রিসিভার
mp = os.path.join(MAIN, 'AndroidManifest.xml')
m = open(mp, encoding='utf-8').read()
if 'MmWidgetProvider' not in m:
    rcv = ('    <receiver android:name=".MmWidgetProvider" android:exported="true" android:label="Madrasa Management">\n'
           '        <intent-filter>\n'
           '            <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />\n'
           '        </intent-filter>\n'
           '        <meta-data android:name="android.appwidget.provider" android:resource="@xml/mm_widget_info" />\n'
           '    </receiver>\n')
    if '</application>' not in m:
        sys.exit('AndroidManifest.xml-এ </application> পাওয়া যায়নি')
    m = m.replace('</application>', rcv + '</application>', 1)
    write(mp, m)
    print('Manifest-এ রিসিভার যোগ হয়েছে')
else:
    print('Manifest-এ রিসিভার আগে থেকেই আছে')

# Manifest: পিরিয়ডের ঘণ্টার অনুমতি ও রিসিভার
m = open(mp, encoding='utf-8').read()
if 'BellReceiver' not in m:
    perms = ''.join('    <uses-permission android:name="android.permission.%s"%s />\n' % (n, x) for n, x in [
        ('WAKE_LOCK', ''), ('RECEIVE_BOOT_COMPLETED', ''), ('USE_EXACT_ALARM', ''),
        ('SCHEDULE_EXACT_ALARM', ' android:maxSdkVersion="32"'), ('REQUEST_IGNORE_BATTERY_OPTIMIZATIONS', '')])
    rcv2 = ('    <receiver android:name=".BellReceiver" android:exported="false" />\n'
            '    <receiver android:name=".BellBootReceiver" android:exported="true">\n'
            '        <intent-filter>\n'
            '            <action android:name="android.intent.action.BOOT_COMPLETED" />\n'
            '            <action android:name="android.intent.action.MY_PACKAGE_REPLACED" />\n'
            '        </intent-filter>\n'
            '    </receiver>\n')
    if '<application' not in m or '</application>' not in m:
        sys.exit('AndroidManifest.xml-এ application ট্যাগ পাওয়া যায়নি')
    m = m.replace('<application', perms + '    <application', 1)
    m = m.replace('</application>', rcv2 + '</application>', 1)
    write(mp, m)
    print('Manifest-এ ঘণ্টার অনুমতি ও রিসিভার যোগ হয়েছে')
else:
    print('Manifest-এ ঘণ্টার রিসিভার আগে থেকেই আছে')

# Gradle: lint-এর কারণে বিল্ড যেন না থামে
gp = os.path.join('android', 'app', 'build.gradle')
g = open(gp, encoding='utf-8').read()
if 'mm_widget_lint' not in g:
    g2, n = re.subn(r'(^|\n)(android\s*\{)', r'\1\2\n    // mm_widget_lint\n    lint {\n        abortOnError false\n        checkReleaseBuilds false\n    }', g, count=1)
    if n:
        write(gp, g2)
        print('build.gradle-এ lint সেটিং যোগ হয়েছে')
    else:
        print('সতর্কতা: build.gradle-এ android { পাওয়া যায়নি, lint সেটিং বসানো হয়নি')
print('উইজেট সেটআপ শেষ')
